(7598208, 1226514, 173844, '<td valign="top">Very nice image. Handsome composition, with the hummingbird like a pendant under a neckline of flowers.</td>', 'Very nice image. Handsome composition, with the hummingbird like a pendant under a neckline of flowers.', '2018-10-05 15:52:56.000000', NULL, 1),
